<script lang="ts">
	import { privateFeedIdentity } from "$platform/private-feed";
	import { page } from "$app/state";
	import { Constants } from "$lib";
	import ErrorComponent from "$lib/components/ErrorComponent.svelte";
	import Grid from "$lib/components/ui/Grid.svelte";
	import * as Empty from "$lib/components/ui/empty";
	import { Spinner } from "$lib/components/ui/spinner";
	import { onMount } from "svelte";
	import DraftSearchEntry from "./DraftSearchEntry.svelte";

	let {
		feed = $bindable(),
		onSearch
	}: {
		feed: MangaFeedResponse | undefined;
		onSearch: () => Promise<void>;
	} = $props();
	let isMounted = $state(false);
	let error = $state<Constants.Error.Error>();

	let privateMounted = $state(false), privateDisposed = false, privateGeneration = 0;
	onMount(() => { privateMounted = true; return () => { privateDisposed = true; privateGeneration++; feed = undefined; }; });
	$effect(() => {
		const identity = $privateFeedIdentity;
		if (!privateMounted || privateDisposed) return;
		const generation = ++privateGeneration;
		feed = undefined; error = undefined; isMounted = false;
		void onSearch().then(() => { if (!privateDisposed && generation === privateGeneration && identity === $privateFeedIdentity) isMounted = true; }).catch(cause => {
			if (privateDisposed || generation !== privateGeneration || identity !== $privateFeedIdentity) return;
			feed = undefined; error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown;
		});
	});
</script>

{#if error}
	<ErrorComponent {error} />
{:else if isMounted}
	{#if feed?.data?.length}
		<Grid class="gap-1" breakpoints={{ 0: 3, 1400: 2, 920: 1 }}>
			{#each feed.data as manga, i (manga)}
				<DraftSearchEntry bind:entries={feed.data} bind:manga={feed.data[i]} />
			{/each}
		</Grid>
	{:else}
		<Empty.Root>
			<Empty.Header>
				<Empty.Title>No results found</Empty.Title>
				{#if window.location.search}
					<Empty.Description>Try adjusting your search or using different keywords.</Empty.Description>
				{:else}
					<Empty.Description>You haven't created any drafts yet.</Empty.Description>
				{/if}
			</Empty.Header>
		</Empty.Root>
	{/if}
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
